<script setup>
import {ref,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {request} from './client'
const props=defineProps({institute:{type:Object,required:true}}),emit=defineEmits(['close'])
const dialog=ref(null),details=ref(null),result=ref(null),busy=ref(false),error=ref(''),confirmed=ref(false),language=ref('en')
let previousFocus
async function load(){busy.value=true;error.value='';try{details.value=await request('campus_join','details',{},'GET')}catch(e){error.value=e.message}finally{busy.value=false}}
async function register(){if(busy.value||!confirmed.value||!details.value?.phone_verified)return;busy.value=true;error.value='';try{result.value=await request('campus_join',props.institute.kind==='Teacher'?'register_teacher':'register_student',{profile:props.institute.name,...(props.institute.kind==='Institute'?{language:language.value}:{})})}catch(e){error.value=e.message}finally{busy.value=false}}
async function enter(){busy.value=true;error.value='';try{await request('campus_context','select',{institute:result.value.institute});window.location.assign('/campus')}catch(e){error.value=e.message;busy.value=false}}
function close(){if(!busy.value){dialog.value?.close();emit('close')}}
onMounted(async()=>{previousFocus=document.activeElement;await nextTick();dialog.value.showModal();load()})
onBeforeUnmount(()=>{dialog.value?.close();previousFocus?.focus?.()})
</script>
<template><dialog ref="dialog" class="institute-registration" aria-labelledby="institute-register-title" @cancel.prevent="close"><button class="registration-close" aria-label="Close registration" :disabled="busy" @click="close">×</button><span class="eyebrow">YOUR NEXT LEARNING CHAPTER</span><h2 id="institute-register-title">{{result?'You’re registered!':'Register with '+institute.display_name}}</h2><p v-if="busy" role="status">{{result?'Opening your institute…':'Please wait…'}}</p><p v-if="error" role="alert">{{error}}</p><section v-if="result" role="status"><p>You’re registered with {{result.institute_title}}.</p><p>Your student number</p><strong class="student-number">{{result.student_number}}</strong><p>Class enrollment is separate. Joining an institute does not unlock paid classes.</p><button v-if="result.institute" class="button primary" :disabled="busy" @click="enter">Switch to this institute →</button></section><form v-else-if="details" @submit.prevent="register"><p>We’ll use your account details below. Update your profile first if anything needs correcting.</p><div class="registration-fields"><label>First name<input :value="details.first_name" readonly autocomplete="off"></label><label>Last name<input :value="details.last_name" readonly autocomplete="off"></label><label>Email<input :value="details.email" readonly type="email" autocomplete="off"></label><label>Verified phone<input :value="details.phone||'Verification needed'" readonly autocomplete="off"></label></div><p v-if="!details.phone_verified">Verify your mobile number in your profile before registering.</p><label v-if="institute.kind==='Institute'">Preferred language<select v-model="language"><option value="en">English</option><option value="si">Sinhala</option><option value="ta">Tamil</option></select></label><label class="registration-consent"><input v-model="confirmed" type="checkbox" required :disabled="busy">I confirm these details and want to register with {{institute.display_name}}.</label><p>You’ll receive a student number for this institute. Following an institute remains a separate preference.</p><button class="button primary" :disabled="busy||!confirmed||!details.phone_verified">Register now</button></form><button v-else-if="!busy" class="button subtle" @click="load">Try again</button></dialog></template>
<style scoped>.institute-registration{position:fixed;inset:0;margin:auto;width:min(620px,calc(100vw - 32px));max-height:90vh;overflow:auto;border:1px solid #e6def0;border-radius:22px;padding:32px;background:white;color:#392c48;box-sizing:border-box}.institute-registration::backdrop{background:#24133588}.institute-registration h2{font-size:25px;margin:16px 32px 16px 0}.institute-registration p{font-size:14px;line-height:1.7;margin:14px 0}.registration-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:22px 0}.registration-fields label{display:grid;gap:8px;font-size:13px}.registration-fields input{box-sizing:border-box;width:100%;padding:12px;border:1px solid #ded4e9;border-radius:10px;background:#faf8fd;color:#483952;font:inherit}.registration-consent{display:flex;align-items:start;gap:10px;font-size:14px;line-height:1.6}.registration-consent input{margin-top:5px}.registration-close{position:absolute;right:16px;top:12px;background:none;border:0;font-size:28px;cursor:pointer}.student-number{display:block;font-size:24px;padding:16px;background:#f4eefb;border-radius:12px}@media(max-width:500px){.registration-fields{grid-template-columns:1fr}.institute-registration{padding:24px}}</style>
